create table if not exists public.universities (
  id uuid primary key default gen_random_uuid(), slug text not null unique,
  name_sr text not null, name_en text not null, display_order integer not null default 0,
  active boolean not null default true
);
create table if not exists public.faculties (
  id uuid primary key default gen_random_uuid(), university_id uuid not null references public.universities(id) on delete cascade,
  name_sr text not null, name_en text not null, active boolean not null default true,
  unique(university_id,name_sr)
);
alter table public.universities enable row level security; alter table public.faculties enable row level security;
grant select on public.universities,public.faculties to anon,authenticated;
drop policy if exists "public reads universities" on public.universities; create policy "public reads universities" on public.universities for select using(active);
drop policy if exists "public reads faculties" on public.faculties; create policy "public reads faculties" on public.faculties for select using(active);

