insert into public.faculties(university_id,name_sr,name_en)
select u.id,s.name_sr,s.name_en from seed s join public.universities u on u.slug=s.university_slug
on conflict(university_id,name_sr) do update set name_en=excluded.name_en,active=true;

alter table public.profiles add column if not exists university_id uuid references public.universities(id);
alter table public.profiles add column if not exists faculty_id uuid references public.faculties(id);
alter table public.recruits add column if not exists university_id uuid references public.universities(id);
alter table public.recruits add column if not exists faculty_id uuid references public.faculties(id);

create table if not exists public.tour_stops(id uuid primary key default gen_random_uuid(),date date not null,municipality text not null,location_name text not null,status text not null default 'scheduled' check(status in('scheduled','in_progress','completed','cancelled')),latitude double precision,longitude double precision,notes text,created_by uuid references public.profiles(id),created_at timestamptz not null default now());
alter table public.tour_stops enable row level security; grant select on public.tour_stops to authenticated; grant insert,update,delete on public.tour_stops to authenticated;
create policy "approved users read tour stops" on public.tour_stops for select to authenticated using(public.is_approved_user()); create policy "coordinators manage tour stops" on public.tour_stops for all to authenticated using(public.is_admin_or_coordinator()) with check(public.is_admin_or_coordinator());

create table if not exists public.website_leads(id uuid primary key default gen_random_uuid(),full_name text not null,email text not null,phone_number text,city_village text,university_id uuid references public.universities(id),faculty_id uuid references public.faculties(id),interested_in_poll_watching boolean not null default false,status text not null default 'new' check(status in('new','reviewed','converted','rejected')),notes text,created_at timestamptz not null default now(),reviewed_by uuid references public.profiles(id),reviewed_at timestamptz);
alter table public.website_leads enable row level security; grant insert on public.website_leads to anon,authenticated; grant select,update on public.website_leads to authenticated;
create policy "public submits website leads" on public.website_leads for insert to anon,authenticated with check(status='new' and reviewed_by is null); create policy "admins read website leads" on public.website_leads for select to authenticated using(public.is_admin());
create or replace function public.admin_review_website_lead(target_id uuid,new_status text) returns void language plpgsql security definer set search_path=public as $$ begin if not public.is_admin() then raise exception 'Admin access required'; end if; if new_status not in('reviewed','converted','rejected') then raise exception 'Invalid status'; end if; update public.website_leads set status=new_status,reviewed_by=auth.uid(),reviewed_at=now() where id=target_id; end $$; grant execute on function public.admin_review_website_lead(uuid,text) to authenticated;

create table if not exists public.field_documents(id uuid primary key default gen_random_uuid(),slug text not null unique,title_sr text not null,title_en text not null,content_sr text not null,content_en text not null,category text not null default 'guideline',display_order integer not null default 0,active boolean not null default true,updated_at timestamptz not null default now());
alter table public.field_documents enable row level security; grant select on public.field_documents to authenticated; create policy "approved users read field docs" on public.field_documents for select to authenticated using(public.is_approved_user());
insert into public.field_documents(slug,title_sr,title_en,content_sr,content_en,category,display_order) values
('verify-identity','Provera identiteta volontera','Volunteer identity verification','Nosite zvaničnu akreditaciju. Predstavite se imenom i timom. Nikada ne fotografišite lične dokumente građana i ne zapisujte JMBG.','Carry official accreditation. Introduce yourself and your team. Never photograph identity documents or record personal identification numbers.','verification',1),
('field-safety','Bezbednost na terenu','Field safety','Radite u paru kada je moguće. Obavestite koordinatora o ruti. Ne ulazite u prostor ako se ne osećate bezbedno. U hitnom slučaju pozovite 112.','Work in pairs where possible. Share your route with the coordinator. Do not enter a space if you feel unsafe. Call 112 in an emergency.','safety',2),
('data-privacy','Zaštita podataka','Data protection','Beležite samo podatke potrebne za terenski rad. Ne delite izvoze, fotografije ni kontakt podatke van odobrenih kanala SUSS-a.','Record only data needed for field work. Do not share exports, photos, or contact details outside approved SUSS channels.','privacy',3),
('incident-protocol','Protokol za incidente','Incident protocol','Sačuvajte bezbednu udaljenost, zabeležite proverljive činjenice, lokaciju i vreme. Ne ulazite u raspravu i odmah eskalirajte kritične slučajeve koordinatoru.','Keep a safe distance and record verifiable facts, location, and time. Do not confront anyone; escalate critical cases to the coordinator immediately.','safety',4)
on conflict(slug) do update set title_sr=excluded.title_sr,title_en=excluded.title_en,content_sr=excluded.content_sr,content_en=excluded.content_en,category=excluded.category,display_order=excluded.display_order,active=true;

create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path=public as $$
declare lead_status text;
begin
  select status into lead_status from public.website_leads where lower(email)=lower(new.email) and status='converted' order by reviewed_at desc limit 1;
  insert into public.profiles(id,full_name,email,phone_number,role,approval_status,university_id,faculty_id)
  values(new.id,coalesce(new.raw_user_meta_data->>'full_name',split_part(new.email,'@',1),new.phone,'Volunteer'),new.email,new.phone,'canvasser',case when lead_status='converted' then 'approved'::public.profile_approval_status else 'pending'::public.profile_approval_status end,nullif(new.raw_user_meta_data->>'university_id','')::uuid,nullif(new.raw_user_meta_data->>'faculty_id','')::uuid)
  on conflict(id) do update set email=excluded.email;
  return new;
end $$;

drop function if exists public.update_own_profile(text,text,text,text,text);
create function public.update_own_profile(new_full_name text,new_phone text,new_region text,new_university_id uuid,new_faculty_id uuid,new_language text)
returns void language plpgsql security definer set search_path=public as $$
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if length(trim(new_full_name))<2 or new_language not in('sr','en') then raise exception 'Invalid profile'; end if;
  if new_faculty_id is not null and not exists(select 1 from public.faculties where id=new_faculty_id and university_id=new_university_id and active) then raise exception 'Faculty does not belong to selected university'; end if;
  update public.profiles set full_name=trim(new_full_name),phone_number=nullif(trim(new_phone),''),assigned_region=nullif(trim(new_region),''),university_id=new_university_id,faculty_id=new_faculty_id,faculty=(select name_sr from public.faculties where id=new_faculty_id),preferred_language=new_language where id=auth.uid();
end $$;
revoke all on function public.update_own_profile(text,text,text,uuid,uuid,text) from public; grant execute on function public.update_own_profile(text,text,text,uuid,uuid,text) to authenticated;
